BEGIN TRANSACTION;
CREATE TABLE deals (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                date TEXT NOT NULL,
                symbol TEXT NOT NULL,
                client_name TEXT NOT NULL,
                side TEXT NOT NULL,
                quantity INTEGER,
                price REAL,
                deal_type TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(date, symbol, client_name, side)
            );
CREATE TABLE flags (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                scan_date TEXT NOT NULL,
                symbol TEXT NOT NULL,
                company TEXT,
                industry TEXT,
                current_price REAL,
                prev_close REAL,
                price_change REAL,
                current_volume INTEGER,
                avg_volume_20d REAL,
                volume_ratio REAL,
                score REAL DEFAULT 0.0,
                status TEXT DEFAULT 'ACTIVE',
                catalyst_state TEXT DEFAULT 'NONE',
                delivery_pct REAL,
                run_type TEXT NOT NULL DEFAULT 'eod',
                is_control INTEGER NOT NULL DEFAULT 0,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(symbol, scan_date, run_type)
            );
CREATE TABLE holidays (
                date TEXT PRIMARY KEY,
                holiday_description TEXT,
                trading_holiday INTEGER DEFAULT 1
            );
CREATE TABLE outcomes (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                flag_id INTEGER NOT NULL REFERENCES flags(id) ON DELETE CASCADE,
                horizon_days INTEGER NOT NULL,
                entry_price REAL,
                forward_return REAL,
                benchmark_return REAL,
                excess_return REAL,
                announcement_found INTEGER DEFAULT 0,
                announcement_type TEXT,
                is_material INTEGER DEFAULT 0,
                announcement_date TEXT,
                announcement_title TEXT,
                announcement_url TEXT,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(flag_id, horizon_days)
            );
CREATE TABLE run_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                run_timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                run_type TEXT NOT NULL,
                source_used TEXT,
                runtime_seconds REAL,
                rows_scanned INTEGER DEFAULT 0,
                flags_generated INTEGER DEFAULT 0,
                status TEXT NOT NULL,
                error_message TEXT
            );
CREATE INDEX idx_flags_date ON flags(scan_date);
CREATE INDEX idx_flags_symbol ON flags(symbol);
CREATE INDEX idx_flags_status ON flags(status);
CREATE INDEX idx_flags_control ON flags(is_control);
CREATE INDEX idx_outcomes_flag ON outcomes(flag_id);
CREATE INDEX idx_deals_lookup ON deals(date, symbol);
DELETE FROM "sqlite_sequence";
COMMIT;
